def maximum_incremental_exchange_drinks(num_bottles,num_exchange):
    consumed=num_bottles;empties=num_bottles
    while empties>=num_exchange:
        empties-=num_exchange;num_exchange+=1
        consumed+=1;empties+=1
    return consumed

